# Generated by manage.py generate_test_cases.
from django.contrib.contenttypes.models import ContentType
from django.http import HttpResponse

from bloomerp.models.application_field import ApplicationField
from bloomerp.models.users.user_list_view_preference import UserListViewPreference
from bloomerp.services.preference_services import PreferenceManager
from bloomerp.tests.base import (
    BloomerpComponentTestCase,
    ExpectedResult,
    RequestScenario,
)


class TestNewPreferenceComponent(BloomerpComponentTestCase):
    """Tests function `new_preference` from `bloomerp/components/preferences/new_preference.py`."""

    view_name = "components_new_preference"

    def get_test_scenarios(self) -> list[RequestScenario]:
        """Check that creating a named preference copies the active layout."""
        return [
            RequestScenario(
                name="Create and select a named copy of the current Kanban preference",
                method="POST",
                user=self.admin_user,
                view_kwargs={"model": "UserListViewPreference"},
                prepare=self.prepare_selected_layout,
                expected=ExpectedResult(
                    status_code=204,
                    response_validators=self.selected_copy_matches_source,
                ),
            ),
        ]

    def prepare_selected_layout(self, scenario: RequestScenario) -> None:
        """Save a customized source layout and set the scope of the new preference."""
        content_type = ContentType.objects.get_for_model(self.CustomerModel)
        self.source = PreferenceManager(self.admin_user).get_or_create_selected(
            UserListViewPreference,
            {"content_type_id": content_type.pk},
        )
        self.source.view_type = "kanban"
        self.source.options = {"kanban": {"page_size": 50}}
        visible_field = ApplicationField.get_by_field(self.CustomerModel, "first_name")
        self.source.set_visible_field_ids("kanban", [visible_field.pk])
        self.source.save(update_fields=["view_type", "options", "display_fields"])
        scenario.data = {"name": "Ops board", "content_type_id": content_type.pk}

    def selected_copy_matches_source(self, _response: HttpResponse) -> bool:
        """Require a distinct selected preference with the source layout settings."""
        self.source.refresh_from_db()
        selected = UserListViewPreference.get_selected_for_user(
            self.admin_user, self.source.content_type
        )
        return (
            selected is not None
            and selected.pk != self.source.pk
            and selected.name == "Ops board"
            and not self.source.selected
            and selected.view_type == self.source.view_type
            and selected.options == self.source.options
            and selected.display_fields == self.source.display_fields
        )
